class _AppState extends State<RabRumahApp> {
  int page=0; JsonMap profile={'name':'RAB Rumahku','logo':'','address':'','contact':''}; List<JsonMap> projects=[]; List<JsonMap> customMaterials=[];
  @override void initState(){super.initState();load();}
  Future<void> load() async { final s=await SharedPreferences.getInstance(); final p=s.getString('profile'),r=s.getString('projects'),m=s.getString('materials'); setState((){if(p!=null)profile=JsonMap.from(jsonDecode(p));if(r!=null)projects=List<JsonMap>.from((jsonDecode(r) as List).map((x)=>JsonMap.from(x)));if(m!=null)customMaterials=List<JsonMap>.from((jsonDecode(m) as List).map((x)=>JsonMap.from(x)));}); }
  Future<void> save() async {final s=await SharedPreferences.getInstance();await s.setString('profile',jsonEncode(profile));await s.setString('projects',jsonEncode(projects));await s.setString('materials',jsonEncode(customMaterials));}
