 @override Widget build(BuildContext c){final r=RabEngine.calculate(input());final s=JsonMap.from(r['summary']);return ListView(padding:const EdgeInsets.all(16),children:[Text('Buat RAB',style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:12),Wrap(spacing:6,children:['Data','Dimensi','Spesifikasi','RAB','Maket'].asMap().entries.map((e)=>ChoiceChip(label:Text('${e.key+1}. ${e.value}'),selected:tab==e.key,onSelected:(_){setState(()=>tab=e.key);})).toList()),const SizedBox(height:16),if(tab==0)...[TextField(controller:name,decoration:const InputDecoration(labelText:'Nama proyek',border:OutlineInputBorder())),const SizedBox(height:10),TextField(controller:owner,decoration:const InputDecoration(labelText:'Pemilik',border:OutlineInputBorder())),const SizedBox(height:10),TextField(controller:location,decoration:const InputDecoration(labelText:'Lokasi',border:OutlineInputBorder()))]else if(tab==1)...[Row(children:[Expanded(child:numBox('Panjang (m)',length,(v)=>setState(()=>length=v))),const SizedBox(width:8),Expanded(child:numBox('Lebar (m)',width,(v)=>setState(()=>width=v)))]),const SizedBox(height:10),Row(children:[Expanded(child:numBox('Tinggi dinding',height,(v)=>setState(()=>height=v))),const SizedBox(width:8),Expanded(child:numBox('Overhang',overhang,(v)=>setState(()=>overhang=v)))]),const SizedBox(height:10),DropdownButtonFormField<int>(value:floors,decoration:const InputDecoration(labelText:'Lantai',border:OutlineInputBorder()),items:[1,2,3].map((x)=>DropdownMenuItem(value:x,child:Text('$x lantai'))).toList(),onChanged:(v)=>setState(()=>floors=v??1)),const SizedBox(height:10),Card(child:ListTile(title:const Text('Luas bangunan'),trailing:Text('${(r['geometry']['floorArea'] as num).toStringAsFixed(2)} m²')))]else if(tab==2)...[select('Dinding',wall,['lightbrick','brick','batako'],(v)=>setState(()=>wall=v)),select('Lantai',floor,['tile','granite'],(v)=>setState(()=>floor=v)),select('Atap',roof,['genteng','metal'],(v)=>setState(()=>roof=v)),select('Plafon',ceiling,['gypsum','grc'],(v)=>setState(()=>ceiling=v)),Row(children:[Expanded(child:numBox('Pintu',doors.toDouble(),(v)=>setState(()=>doors=v.round()))),const SizedBox(width:8),Expanded(child:numBox('Jendela',windows.toDouble(),(v)=>setState(()=>windows=v.round())))])]else if(tab==3)...[SummaryTable(summary:s),const SizedBox(height:12),Text('Komponen: ${(r['items'] as List).length} item')]else...[_Maket(r:r,top:top,onTop:()=>setState(()=>top=!top))],const SizedBox(height:20),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[if(tab>0)OutlinedButton(onPressed:()=>setState(()=>tab--),child:const Text('Kembali'))else const SizedBox(),FilledButton(onPressed:(){if(tab<4)setState(()=>tab++);else finish();},child:Text(tab==4?'Simpan Proyek':'Lanjut'))])]);}
