class HousePainter extends CustomPainter{final JsonMap r;final bool top;HousePainter(this.r,this.top);@override void paint(Canvas c,Size s){final p=Paint()..style=PaintingStyle.stroke..strokeWidth=3;final g=JsonMap.from(r['geometry']);final w=(g['width'] as num).toDouble(),l=(g['length'] as num).toDouble();final scale=.7*s.width/(l>w?l:w);final rect=Rect.fromLTWH((s.width-l*scale)/2,(s.height-w*scale)/2,l*scale,w*scale);c.drawRect(rect,p);if(top){final x=rect.left+rect.width*.45;c.drawLine(Offset(x,rect.top),Offset(x,rect.bottom),p);c.drawLine(Offset(rect.left,rect.top+rect.height*.55),Offset(rect.right,rect.top+rect.height*.55),p);}}@override bool shouldRepaint(covariant HousePainter old)=>old.top!=top;}
